<template>
  <!-- #ifdef H5 -->
  <div class="project-tasks" @keydown="activateButton">
  <!-- #endif -->
  <!-- #ifndef H5 -->
  <view class="project-tasks">
  <!-- #endif -->
    <button role="button" tabindex="0" class="tasks-disclosure" :disabled="!canInteract || busy" :aria-expanded="opened" @tap="toggle">
      <view><text class="tasks-label">长任务<text v-if="dirty"> · 未保存</text></text><text class="tasks-subtitle">先看计划，再授权执行；进度和报告留在项目里。</text></view><text aria-hidden="true">{{ opened ? '−' : '＋' }}</text>
    </button>
    <view v-if="opened" class="tasks-panel">
      <view class="tasks-toolbar"><text class="tasks-kicker">PROJECT / RESEARCH RUNS</text><view class="tasks-actions"><button role="button" tabindex="0" class="tasks-link" :disabled="!canInteract || busy" @tap="refreshList">读取任务</button><button role="button" tabindex="0" v-if="enabled" class="tasks-secondary" :disabled="!canInteract || busy" @tap="newPlan">新建计划 ＋</button></view></view>
      <text class="tasks-note">任务不会因打开页面自动执行，也不会自动轮询或重试。关闭页面后已授权的后台批次可能继续；暂停会阻止后续步骤，不能撤回已经发出的模型调用。</text>
      <text v-if="busy" class="tasks-note" role="status">正在提交或读取任务；不推测模型内部进度…</text>
      <text v-if="error" class="tasks-error" role="alert">{{ error }}</text><text v-if="notice" class="tasks-notice" role="status" aria-live="polite">{{ notice }}</text>
      <text v-if="loaded && !enabled" class="tasks-note">当前服务未开放长任务，没有创建、保存或请求模型。普通聊天仍可使用。</text>
      <template v-if="enabled">
        <view v-if="editorOpen" class="task-editor">
          <view class="tasks-toolbar"><text class="tasks-section">{{ editingId ? '调整这份计划' : '把目标拆成可检查的问题' }}</text><text class="tasks-meta">只保存计划，不使用模型</text></view>
          <text class="tasks-field-label">目标</text><textarea v-model="editor.goal" class="tasks-field" :maxlength="-1" auto-height :disabled="busy || !canInteract" placeholder="这项研究最终要帮助你做什么判断？" aria-label="研究任务目标" />
          <text class="tasks-field-label">约束与交付要求</text><textarea v-model="editor.constraints" class="tasks-field" :maxlength="-1" auto-height :disabled="busy || !canInteract" placeholder="读者、范围、不能跳过的条件，以及希望报告说明的内容" aria-label="研究任务约束" />
          <text class="tasks-meta">目标 {{ Array.from(editor.goal).length }}/1200 · 约束 {{ Array.from(editor.constraints).length }}/1200</text>
          <view v-for="(item,index) in editor.questions" :key="item.id" class="task-question">
            <view class="question-heading"><text class="question-number">{{ String(index+1).padStart(2,'0') }}</text><input v-model="item.title" class="question-title" :maxlength="-1" :disabled="busy || !canInteract" placeholder="给这个问题起个短标题（可选）" :aria-label="'问题'+(index+1)+'标题'" /><button role="button" tabindex="0" v-if="!editingId && editor.questions.length > 1" class="tasks-link" :disabled="busy || !canInteract" @tap="removeQuestion(index)">移除</button></view>
            <textarea v-model="item.question" class="tasks-field" :maxlength="-1" auto-height :disabled="busy || !canInteract" placeholder="一个能独立检查依据的问题；需要比较时写明相同维度和限制" :aria-label="'研究问题'+(index+1)" />
            <text class="tasks-meta">{{ Array.from(item.title).length }}/120 标题 · {{ Array.from(item.question).length }}/1800 问题 · {{ item.document_ids?.length ? `指定 ${item.document_ids.length} 份资料` : '当前项目资料' }}</text>
            <button role="button" tabindex="0" class="tasks-link" :disabled="busy || !canInteract" :aria-expanded="documentScopeId === item.id" @tap="toggleDocumentScope(item)">{{ documentScopeId === item.id ? '收起资料范围' : '限定资料（可选）' }}</button>
            <view v-if="documentScopeId === item.id" class="document-scope">
              <text class="tasks-note">只读取文件名与状态，不读取正文。未指定时使用全项目，新资料也会纳入；指定后仅使用勾选的资料。限定范围可减少无关资料变化带来的重新计算，依赖步骤仍会受上游影响。</text>
              <text v-if="documentsLoaded && !documents.length" class="tasks-note">当前项目没有可列出的资料；已有范围不会自动清空。</text>
              <checkbox-group v-if="documentsLoaded" :key="scopeSelectionRevision" @change="setDocumentScope(item,$event)">
                <label v-for="doc in documents" :key="doc.id" class="scope-document"><checkbox :value="doc.id" :checked="Boolean(item.document_ids?.includes(doc.id))" :disabled="busy || !canInteract || doc.status !== 'ready'" color="#25493e" /><view><text class="scope-filename">{{ doc.filename }}</text><text class="tasks-meta">{{ documentStateLabel(doc.status) }}{{ doc.status !== 'ready' ? ' · 不能新增选入' : '' }}</text></view></label>
              </checkbox-group>
              <view v-for="documentId in unavailableScope(item)" :key="documentId" class="scope-unavailable"><text class="tasks-error">已指定资料目前未就绪或不可见（{{ documentId.slice(0,8) }}…），保留原范围，不自动扩大。</text><button role="button" tabindex="0" class="tasks-link" :disabled="busy || !canInteract" @tap="removeUnavailableDocument(item,documentId)">从此问题移除此项</button></view>
            </view>
            <picker v-if="!editingId && index > 0" :range="dependencyLabels(index)" :value="dependencyIndex(item,index)" :disabled="busy || !canInteract" @change="setDependency(item,index,$event)"><view class="budget-picker">依赖：{{ dependencyLabels(index)[dependencyIndex(item,index)] }} ⌄</view></picker><text v-else-if="item.depends_on?.length" class="tasks-meta">先完成：{{ item.depends_on.join('、') }}</text>
          </view>
          <button role="button" tabindex="0" v-if="!editingId && editor.questions.length < 6" class="tasks-secondary" :disabled="busy || !canInteract" @tap="addQuestion">添加一个问题 ＋</button>
          <view class="plan-preview"><text class="tasks-field-label">执行计划预览</text><text>资料快照核对 → {{ editor.questions.length }} 个分析问题（按依赖顺序）→ 汇集有版本的报告</text><text class="tasks-note">资料核对和报告汇集不调用模型；每个分析问题至多一次生成。后续问题可携带前一步有界产物，仍不是新事实。报告汇集不是额外一轮综合推理，结论仍需你核对。</text></view>
          <text v-if="editingId" class="tasks-note">本版可改问题内容、范围和约束，保留问题编号。需要新增或移除问题时新建计划；保存会使受影响的旧成果失效，不会自动重跑。</text>
          <view class="tasks-actions"><button role="button" tabindex="0" class="tasks-primary" :disabled="busy || !canInteract || !validPlan || saveUncertain" @tap="savePlan">{{ editingId ? '保存新计划版本' : '保存计划，暂不执行' }}</button><button role="button" tabindex="0" class="tasks-link" :disabled="busy || !canInteract" @tap="editorOpen = false">收起草稿</button></view>
        </view>
        <view class="tasks-layout">
          <view class="task-list"><text class="tasks-section">项目任务 <text class="tasks-meta">{{ items.length }}</text></text><text v-if="!items.length" class="tasks-note">还没有任务。从你的真实目标开始，不预置演示成果。</text><button role="button" tabindex="0" v-for="item in items" :key="item.id" class="task-list-item" :class="{'task-selected':task?.id === item.id}" :disabled="busy || !canInteract" @tap="openTask(item.id)"><text class="task-list-goal">{{ item.goal }}</text><text class="tasks-meta">{{ taskStateLabel(item.status) }} · 计划 r{{ item.revision }}</text></button></view>
          <view v-if="task" class="task-detail">
            <view class="tasks-toolbar"><view><text class="tasks-section">{{ task.goal }}</text><text class="tasks-meta">{{ taskStateLabel(task.status) }} · 第 {{ task.generation }} 轮 · 计划 r{{ task.revision }}</text></view><button role="button" tabindex="0" class="tasks-link" :disabled="busy || !canInteract" @tap="refreshTask">刷新进度</button></view>
            <text v-if="task.constraints" class="task-constraints">{{ task.constraints }}</text><text class="tasks-progress" role="status">服务确认 {{ completedSteps }}/{{ task.steps.length }} 步已完成<text v-if="task.run_remaining !== null"> · 本批剩余至多 {{ task.run_remaining }} 次模型调用</text></text>
            <view v-for="(step,index) in task.steps" :key="step.id" class="task-step" :class="{'step-completed':step.status === 'completed'}"><text class="step-index">{{ step.status === 'completed' ? '✓' : index+1 }}</text><view class="step-body"><view class="tasks-toolbar"><text class="step-title">{{ stepTitle(step) }}</text><text class="step-state">{{ taskStateLabel(step.status) }}</text></view><text v-if="step.kind === 'analysis'" class="tasks-note">{{ step.question }}</text><text v-if="step.kind === 'analysis'" class="tasks-meta">资料范围：{{ step.document_ids?.length ? `指定 ${step.document_ids.length} 份` : '全项目（含新增资料）' }} · 前序：{{ dependencyNames(step) }}</text><text v-if="step.reason" class="tasks-error">{{ reasonLabel(step.reason) }}</text><text v-if="step.kind !== 'analysis'" class="tasks-meta">程序步骤 · 不请求模型</text></view></view>
            <text v-if="task.status === 'blocked' || uncertainRun || hasUnknownOutcome" class="tasks-error">有步骤受阻或请求结果未确认。先读取服务状态；不会自动重试可能已经计费的请求，也不能把未完成结果当成报告。</text>
            <button role="button" tabindex="0" v-if="canRetryFailed" class="tasks-secondary" :disabled="busy || !canInteract" @tap="controlTask('retry_failed')">重建失败步骤</button>
            <text v-if="canRetryFailed" class="tasks-note">仅重新建立已确认失败的待办，不执行模型；之后需要另行批准额度。</text>
            <view class="run-budget"><text class="tasks-field-label">这次最多授权几次模型调用？</text><picker :range="budgetOptions" :value="budget-1" :disabled="busy || !canInteract" @change="setBudget"><view class="budget-picker">{{ budget }} 次 ⌄</view></picker><text class="tasks-note">按批准次数预扣每日问答额度，未用完不退。每次输出上限 8192 tokens，另计输入；这不是金额上限。资料变化或失败会停止，不自动追加额度。</text></view>
            <view class="tasks-actions"><button role="button" tabindex="0" class="tasks-primary" :disabled="busy || !canInteract || !canRun || Boolean(uncertainRun)" @tap="runTask">{{ task.status === 'paused' ? '确认额度并继续' : '确认额度后执行' }}</button><button role="button" tabindex="0" v-if="task.status === 'running' || task.status === 'ready'" class="tasks-secondary" :disabled="busy || !canInteract" @tap="controlTask('pause')">暂停后续步骤</button><button role="button" tabindex="0" v-if="task.status === 'stale'" class="tasks-secondary" :disabled="busy || !canInteract" @tap="controlTask('refresh')">按现有资料重建待办</button><button role="button" tabindex="0" v-if="!['running','cancelled'].includes(task.status)" class="tasks-link" :disabled="busy || !canInteract" @tap="editPlan">调整计划</button><button role="button" tabindex="0" v-if="!['completed','cancelled'].includes(task.status)" class="tasks-link" :disabled="busy || !canInteract" @tap="controlTask('cancel')">取消任务</button></view>
            <view class="task-reports"><text class="tasks-section">报告版本</text><text class="tasks-note">每次打开和带走前重新核对来源。失效或撤回版本不显示旧正文；生成完成也不表示事实已验证。</text><view class="tasks-actions"><button role="button" tabindex="0" v-for="item in task.artifact_versions" :key="item.version" class="tasks-secondary" :disabled="busy || !canInteract" @tap="viewArtifact(item.version)">v{{ item.version }} · {{ item.status === 'current' ? '查看' : item.status === 'stale' ? '已失效' : '已撤回' }}</button></view><text v-if="!task.artifact_versions.length" class="tasks-note">报告尚未形成；完成单个步骤不冒充最终交付。</text>
              <view v-if="artifact" class="task-artifact"><text class="tasks-field-label">报告 v{{ artifact.version }}</text><text v-if="!artifact.available" class="tasks-error">此版本的原文或成果已不可用，不展示、复制或下载旧内容。</text><template v-else><AnswerBody :text="artifact.content" /><view class="tasks-actions"><button role="button" tabindex="0" class="tasks-secondary" :disabled="busy || !canInteract" @tap="deliverArtifact('copy')">复制此版本</button><!-- #ifdef H5 --><button role="button" tabindex="0" class="tasks-secondary" :disabled="busy || !canInteract" @tap="deliverArtifact('download')">下载 Markdown</button><!-- #endif --></view><text class="tasks-note">只在你点击后带到剪贴板或本地文件，不上传、不创建公开链接；离开应用后的副本无法随源撤回。</text></template></view>
            </view>
          </view>
          <view v-else class="tasks-empty"><text class="tasks-section">进展不靠猜。</text><text class="tasks-note">选择任务，查看服务确认的步骤、阻塞原因和报告版本。授权前先检查问题是否覆盖你的目标。</text></view>
        </view>
      </template>
    </view>
  <!-- #ifndef H5 -->
  </view>
  <!-- #endif -->
  <!-- #ifdef H5 -->
  </div>
  <!-- #endif -->
</template>

<script setup>
import {computed, ref, watch, onBeforeUnmount} from 'vue';
import {onHide, onUnload} from '@dcloudio/uni-app';
import {createProjectTasksClient, taskPlan, taskStateLabel} from '../services/project-tasks.js';
import {createQueryRequestIdAsync, researchConnectionKey} from '../services/api.js';
import {downloadResearchMarkdown} from '../services/research-export.js';
import AnswerBody from './AnswerBody.vue';
const props=defineProps({sessionId:{type:String,default:''},identity:{type:String,default:''},active:{type:Boolean,default:false},demo:{type:Boolean,default:false},disabled:{type:Boolean,default:false}});
const emit=defineEmits(['busy','dirty']);
const client=createProjectTasksClient();
const blank=()=>({goal:'',constraints:'',questions:[{id:'q1',title:'',question:''}]});
const opened=ref(false),loaded=ref(false),enabled=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const items=ref([]),task=ref(null),artifact=ref(null),editor=ref(blank()),editorOpen=ref(false),editingId=ref(''),editingRevision=ref(0),savedEditor=ref(JSON.stringify(blank())),saveUncertain=ref(false),uncertainRun=ref('');
const documents=ref([]),documentsLoaded=ref(false),documentScopeId=ref(''),scopeSelectionRevision=ref(0);
const budget=ref(1),budgetOptions=['1 次','2 次','3 次','4 次','5 次','6 次'];
let generation=0,scopeSession=props.sessionId,scopeIdentity=props.identity,questionSequence=1;
const canInteract=computed(()=>props.active && !props.demo && !props.disabled && Boolean(props.sessionId) && props.identity === researchConnectionKey());
const validPlan=computed(()=>{try{taskPlan(editor.value);return true;}catch{return false;}});
const dirty=computed(()=>JSON.stringify(editor.value)!==savedEditor.value);
const completedSteps=computed(()=>task.value?.steps.filter(step=>step.status === 'completed').length || 0);
const hasUnknownOutcome=computed(()=>task.value?.reason === 'provider_outcome_unknown' || task.value?.steps.some(step=>step.reason === 'provider_outcome_unknown'));
const canRun=computed(()=>task.value && ['ready','paused'].includes(task.value.status) && !hasUnknownOutcome.value && !task.value.steps.some(step=>['running','blocked'].includes(step.status)));
const canRetryFailed=computed(()=>task.value && !['running','cancelled','stale','completed'].includes(task.value.status) && !uncertainRun.value && !hasUnknownOutcome.value && !task.value.steps.some(step=>step.status === 'running') && task.value.steps.some(step=>step.status === 'blocked' && ['provider_failed','source_unavailable','invalid_result','dependency_blocked','provenance_unavailable'].includes(step.reason)));
function stepTitle(step){return step.kind==='inventory'?'核对项目资料':step.kind==='report'?'汇集研究报告':step.title || step.question;}
function dependencyNames(step){return step.depends_on.map(id=>{const previous=task.value?.steps.find(item=>item.id===id);return previous?stepTitle(previous):'待核对的前序步骤';}).join('、') || '无';}
function reasonLabel(code){const labels={source_changed:'资料或计划已有变化，请核对后重建待办。',source_revoked:'这一步使用的资料已撤回，旧结果不能继续使用。',source_unavailable:'需要的资料暂不可用，请先检查资料状态。',provenance_unavailable:'结果的原文依据无法核对，暂不交付旧结果。',provider_failed:'这次模型请求已确认失败；可先重建待办，再另行批准额度。',provider_outcome_unknown:'上次模型调用结果还未确认，可能已经计费；请先刷新核对，不要重试。',invalid_result:'这次返回未形成可交付结果，不能当作已完成。',dependency_blocked:'需要的前序成果还不可用，请先处理前序步骤。',budget_exhausted:'本批批准次数已用完；继续执行需要你另行批准。',process_restarted:'服务重新启动过，请先刷新核对已有回执。',user_paused:'已按你的要求暂停后续步骤。',user_cancelled:'已按你的要求取消任务。'};return typeof labels[code]==='string'?labels[code]:'这一步暂时不能继续，请刷新状态核对；不会自动重试。';}
watch(dirty,value=>emit('dirty',value));
function setBusy(value){busy.value=value;emit('busy',value);}
function activateButton(event){if(!canInteract.value || busy.value || !event || event.repeat || event.isComposing || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || !['Enter',' ','Spacebar'].includes(event.key))return;const button=event.target?.closest?.('[role="button"]');if(!button || button.hasAttribute?.('disabled') || button.getAttribute?.('aria-disabled')==='true' || typeof button.click!=='function')return;event.preventDefault?.();button.click();}
function clearDocumentScope(){documents.value=[];documentsLoaded.value=false;documentScopeId.value='';scopeSelectionRevision.value++;}
function clearView(){generation++;opened.value=false;loaded.value=false;enabled.value=false;items.value=[];task.value=null;artifact.value=null;clearDocumentScope();error.value='';notice.value='';setBusy(false);}
function reset(){clearView();editor.value=blank();savedEditor.value=JSON.stringify(editor.value);editingId.value='';editorOpen.value=false;saveUncertain.value=false;uncertainRun.value='';questionSequence=1;}
watch(()=>[props.sessionId,props.identity],([session,identity])=>{if(identity!==scopeIdentity || (session && scopeSession && session!==scopeSession))reset();else clearView();if(session)scopeSession=session;scopeIdentity=identity;});
watch(()=>props.active,value=>{if(!value)clearView();});
function capture(){const token=++generation,session=props.sessionId,key=props.identity;return {session,current:()=>token===generation && props.active && session===props.sessionId && key===props.identity && key===researchConnectionKey()};}
async function operation(work){if(!canInteract.value || busy.value)return;const ctx=capture();setBusy(true);error.value='';notice.value='';try{await work(ctx);}catch(issue){if(ctx.current())error.value=issue?.status===409?'任务版本或状态已改变。草稿仍保留，请先手动读取任务再决定，不会自动覆盖或重发。':typeof issue?.message==='string'?issue.message:'未能确认操作结果，请手动读取状态；没有自动重试。';}finally{if(ctx.current())setBusy(false);}}
function confirmed(title,content,confirmText='确认'){return new Promise(resolve=>uni.showModal({title,content,confirmText,cancelText:'先不继续',success:value=>resolve(value?.confirm===true),fail:()=>resolve(false)}));}
function adopt(value){task.value=value;artifact.value=null;const index=items.value.findIndex(item=>item.id===value.id);items.value=index<0?[value,...items.value]:items.value.map(item=>item.id===value.id?value:item);if(uncertainRun.value && value.run_id===uncertainRun.value)uncertainRun.value='';}
async function toggle(){if(!canInteract.value || busy.value)return;if(opened.value){opened.value=false;artifact.value=null;return;}opened.value=true;await refreshList();}
async function refreshList(){await operation(async ctx=>{artifact.value=null;const result=await client.load(ctx.session,{isCurrent:ctx.current});if(!ctx.current())return;loaded.value=true;enabled.value=result.enabled;items.value=result.items;task.value=null;notice.value='已读取服务记录，没有触发模型。';});}
async function openTask(id){await operation(async ctx=>{artifact.value=null;const result=await client.detail(ctx.session,id,{isCurrent:ctx.current});if(ctx.current())adopt(result);});}
async function refreshTask(){if(task.value)await openTask(task.value.id);}
async function newPlan(){if(!canInteract.value || busy.value || !enabled.value)return;const ctx=capture();if(dirty.value && !(await confirmed('新建另一份计划？','未保存草稿只在本页内存中；继续会放弃它，不影响服务上已保存的任务。')))return;if(!ctx.current())return;clearDocumentScope();editor.value=blank();savedEditor.value=JSON.stringify(editor.value);editingId.value='';editorOpen.value=true;saveUncertain.value=false;questionSequence=1;}
function addQuestion(){if(!canInteract.value || busy.value || editingId.value || editor.value.questions.length>=6)return;editor.value.questions.push({id:'q'+(++questionSequence),title:'',question:'',depends_on:[editor.value.questions.at(-1).id]});}
function removeQuestion(index){if(canInteract.value && !busy.value && !editingId.value && editor.value.questions.length>1){const [removed]=editor.value.questions.splice(index,1);for(const item of editor.value.questions)item.depends_on=(item.depends_on || []).filter(id=>id!==removed.id);}}
function dependencyLabels(index){return ['不依赖其他问题',...editor.value.questions.slice(0,index).map((item,i)=>`${i+1} · ${item.title || item.id}`)];}
function dependencyIndex(item,index){return item.depends_on?.length ? editor.value.questions.slice(0,index).findIndex(prior=>prior.id===item.depends_on[0])+1 : 0;}
function setDependency(item,index,event){if(!canInteract.value || busy.value || editingId.value)return;const value=Number(event?.detail?.value);if(Number.isInteger(value) && value>=0 && value<=index)item.depends_on=value ? [editor.value.questions[value-1].id] : [];}
const documentStateLabel=value=>({ready:'可用于研究',queued:'排队中',processing:'处理中',failed:'处理失败',deleted:'已移除'}[value] || '状态未知');
function unavailableScope(item){return documentsLoaded.value ? (item.document_ids || []).filter(id=>!documents.value.some(doc=>doc.id===id && doc.status==='ready')) : [];}
async function toggleDocumentScope(item){if(!enabled.value || !canInteract.value || busy.value || !editor.value.questions.includes(item))return;if(documentScopeId.value===item.id){clearDocumentScope();return;}await operation(async ctx=>{clearDocumentScope();documentScopeId.value=item.id;const value=await client.documents(ctx.session,{isCurrent:ctx.current});if(!ctx.current() || !editor.value.questions.includes(item))return;documents.value=value;documentsLoaded.value=true;});}
async function changeDocumentScope(item,next,removingUnavailable=false){if(!canInteract.value || busy.value || !documentsLoaded.value || documentScopeId.value!==item.id || !editor.value.questions.includes(item))return;await operation(async ctx=>{try{if(!next.length && item.document_ids?.length && !(await confirmed('切换到全项目资料？','移除最后一份指定资料后，这个问题将使用全项目资料，包括以后新增的资料。保存新计划后范围才会生效。')))return;if(removingUnavailable && next.length && !(await confirmed('移除这份指定资料？','仅调整这个问题的计划范围，不删除原文件。保存后相关旧成果可能失效，不会自动执行。')))return;if(ctx.current() && editor.value.questions.includes(item))item.document_ids=next.length ? [...next] : null;}finally{if(ctx.current())scopeSelectionRevision.value++;}});}
async function setDocumentScope(item,event){const values=event?.detail?.value;if(!Array.isArray(values) || values.length>20 || values.some(id=>!documents.value.some(doc=>doc.id===id && (doc.status==='ready' || item.document_ids?.includes(id)))) || new Set(values).size!==values.length){scopeSelectionRevision.value++;return;}await changeDocumentScope(item,[...new Set([...values,...unavailableScope(item)])]);}
async function removeUnavailableDocument(item,id){if(!unavailableScope(item).includes(id))return;await changeDocumentScope(item,(item.document_ids || []).filter(value=>value!==id),true);}
async function editPlan(){if(!task.value || !canInteract.value || busy.value)return;const ctx=capture(),value=task.value;if(dirty.value && !(await confirmed('读取已保存计划？','当前未保存草稿会被替换，请先保留需要的内容。')))return;if(!ctx.current())return;clearDocumentScope();editor.value={goal:value.goal,constraints:value.constraints,questions:value.steps.filter(step=>step.kind==='analysis').map(step=>({id:step.id,title:step.title,question:step.question,document_ids:step.document_ids,depends_on:step.depends_on.filter(id=>id!=='inventory')}))};editingId.value=value.id;editingRevision.value=value.revision;savedEditor.value=JSON.stringify(editor.value);editorOpen.value=true;saveUncertain.value=false;}
async function savePlan(){if(!enabled.value || !validPlan.value || saveUncertain.value)return;await operation(async ctx=>{const plan=taskPlan(editor.value);let value;try{value=editingId.value?await client.update(ctx.session,editingId.value,editingRevision.value,plan,{isCurrent:ctx.current}):await client.create(ctx.session,plan,{isCurrent:ctx.current});}catch(issue){if(ctx.current() && !issue?.status){saveUncertain.value=true;error.value='保存结果尚未确认。请先读取任务列表检查，不会重复创建。';}throw issue;}if(!ctx.current())return;adopt(value);editingId.value=value.id;editingRevision.value=value.revision;savedEditor.value=JSON.stringify(editor.value);notice.value='计划已保存，没有调用模型。核对步骤后，再明确批准执行额度。';});}
function setBudget(event){const value=Number(event?.detail?.value)+1;if(!busy.value && canInteract.value && Number.isInteger(value) && value>=1 && value<=6)budget.value=value;}
async function runTask(){if(!enabled.value || !canRun.value || uncertainRun.value)return;await operation(async ctx=>{const value=task.value,calls=budget.value;if(!(await confirmed(`批准至多 ${calls} 次模型调用？`,`将预扣 ${calls} 份每日问答额度，未用完不退。每次输出最多 8192 tokens，输入另计；不是金额上限。后台只执行本次批准的批次，失败或状态不明不会自动重试。`,'批准并执行')) || !ctx.current())return;const requestId=await createQueryRequestIdAsync({isCurrent:ctx.current});if(!ctx.current())return;uncertainRun.value=requestId;const result=await client.run(ctx.session,value.id,value.revision,requestId,calls,{isCurrent:ctx.current});if(!ctx.current())return;adopt(result);uncertainRun.value='';notice.value='服务已接收执行请求。下方只显示服务返回的进度；点击刷新读取，不自动轮询。';});}
async function controlTask(action){if(!task.value || !enabled.value || (action==='retry_failed' && !canRetryFailed.value))return;await operation(async ctx=>{const value=task.value;const descriptions={pause:'阻止后续步骤继续。正在执行的模型请求可能仍会完成并计费，不保证即时取消。',cancel:'取消后不再推进任务。已经发出的请求仍可能计费，不能撤回已经导出的副本。',refresh:'按当前资料重新建立待办，旧报告会失效；不会调用模型，之后仍需重新批准额度。',retry_failed:'仅重建已确认失败的步骤，不调用模型。之前的调用可能已经计费，已扣额度不返还；之后需要你重新批准执行，新批准会另耗额度。结果不明的步骤不能重建。'};const titles={pause:'暂停后续步骤？',cancel:'取消这个任务？',refresh:'更新资料快照？',retry_failed:'重建已确认失败的步骤？'};if(!descriptions[action] || !(await confirmed(titles[action],descriptions[action])) || !ctx.current())return;const result=await client.control(ctx.session,value.id,value.revision,action,{isCurrent:ctx.current});if(ctx.current()){adopt(result);notice.value=action==='retry_failed'?'失败待办已重建，没有调用模型。核对后须另外批准新执行额度。':'操作已由服务确认，没有在客户端自动追加执行。';}});}
async function viewArtifact(reportVersion){if(!task.value)return;await operation(async ctx=>{artifact.value=null;const value=await client.artifact(ctx.session,task.value.id,reportVersion,{isCurrent:ctx.current});if(ctx.current())artifact.value=value;});}
async function deliverArtifact(action){if(!task.value || !artifact.value?.available)return;await operation(async ctx=>{const id=task.value.id,v=artifact.value.version;artifact.value=null;const value=await client.artifact(ctx.session,id,v,{isCurrent:ctx.current});if(!ctx.current())return;artifact.value=value;if(!value.available)return;if(!(await confirmed(action==='copy'?'复制当前报告？':'下载当前报告？','报告包含私有资料与待核对结论。副本只由你带走，不公开发布；之后源撤回无法删除已带走的副本。')) || !ctx.current())return;if(action==='copy'){await new Promise((resolve,reject)=>{if(!ctx.current() || typeof uni.setClipboardData!=='function')return reject(new Error('当前环境无法复制'));uni.setClipboardData({data:value.content,showToast:false,success:resolve,fail:reject});});}else downloadResearchMarkdown(value.content,ctx.session,{isCurrent:ctx.current});if(ctx.current())notice.value=action==='copy'?'当前版本已复制，未上传或分享。':'已请求本地下载，未上传或分享。';});}
onHide(clearView);onUnload(reset);onBeforeUnmount(reset);
</script>

