e}.tasks-empty{padding:24px 8px}.task-artifact .tasks-actions{margin-top:18px}@media(max-width:680px){.tasks-layout{grid-template-columns:1fr;gap:14px}.task-list{border-right:0;border-bottom:1px solid #e0e6d8;padding-right:0;padding-bottom:12px}.task-list-item{padding:11px}.task-editor{padding:12px}.tasks-panel{padding:0 12px 16px}.task-question{padding:9px}.task-artifact{padding:11px}.tasks-disclosure{padding:12px}.tasks-actions .tasks-primary{flex:1}.tasks-subtitle{max-width:270px}.task-empty{padding:10px 0}}
